using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap a REST API via HttpClient.
/// Uses constructor injection — the SDK resolves DI services automatically
/// and excludes them from the tool's JSON schema.
/// </summary>
[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        WriteIndented = true,
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
    };

    [McpServerTool, Description("List all users from the API. Returns JSON array of user objects.")]
    public async Task<string> ListUsers(
        [Description("Maximum number of results to return (1-100)")] int limit = 10,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing users with limit={Limit}", limit);

        var response = await httpClient.GetFromJsonAsync<JsonElement>(
            $"/users?_limit={Math.Clamp(limit, 1, 100)}", cancellationToken);

        return JsonSerializer.Serialize(response, JsonOptions);
    }

    [McpServerTool, Description("Get a single user by their numeric ID.")]
    public async Task<string> GetUser(
        [Description("The numeric user ID to look up")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);

        var response = await httpClient.GetAsync($"/users/{userId}", cancellationToken);

        if (!response.IsSuccessStatusCode)
        {
            return $"Error: API returned {(int)response.StatusCode} {response.ReasonPhrase}";
        }

        var content = await response.Content.ReadAsStringAsync(cancellationToken);
        return content;
    }

    [McpServerTool, Description("Create a new user. Returns the created user with assigned ID.")]
    public async Task<string> CreateUser(
        [Description("Full name of the user")] string name,
        [Description("Email address")] string email,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating user {Name}", name);

        var payload = new { name, email };
        var response = await httpClient.PostAsJsonAsync("/users", payload, cancellationToken);

        if (!response.IsSuccessStatusCode)
        {
            return $"Error: API returned {(int)response.StatusCode} {response.ReasonPhrase}";
        }

        var content = await response.Content.ReadAsStringAsync(cancellationToken);
        return content;
    }
}

